package main

func validUsername(s string) bool {
	// Длина в ASCII-символах (байтах): от 3 до 16
	if len(s) < 3 || len(s) > 16 {
		return false
	}

	// Проверяем каждый байт: только [A-Za-z0-9_]
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') ||
			(c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') ||
			c == '_' {
			continue
		}
		return false
	}

	return true
}
